import { logger } from '@/utils/logger';
import type { VoiceOption } from './tts';

// Two in-browser engines add voices on devices whose OS/browser voice list has
// few or no male options. Piper is small and fast on any CPU; Kokoro sounds
// better but needs a working GPU to be quick. Each runs in its own worker so
// only the engine in use is downloaded.
type Engine = 'piper' | 'kokoro';

const ENGINE_PREFIX: Record<Engine, string> = { piper: 'piper:', kokoro: 'kokoro:' };

const PIPER_VOICES = [
  { id: 'en_US-ryan-medium', label: 'Ryan (US male)', lang: 'en-US' },
  { id: 'en_US-joe-medium', label: 'Joe (US male)', lang: 'en-US' },
  { id: 'en_US-john-medium', label: 'John (US male)', lang: 'en-US' },
  { id: 'en_US-bryce-medium', label: 'Bryce (US male)', lang: 'en-US' },
  { id: 'en_US-norman-medium', label: 'Norman (US male)', lang: 'en-US' },
  { id: 'en_US-kusal-medium', label: 'Kusal (US male)', lang: 'en-US' },
  { id: 'en_US-hfc_male-medium', label: 'HFC (US male)', lang: 'en-US' },
  { id: 'en_GB-alan-medium', label: 'Alan (UK male)', lang: 'en-GB' },
  { id: 'en_GB-northern_english_male-medium', label: 'Northern (UK male)', lang: 'en-GB' },
] as const;

const KOKORO_VOICES = [
  { id: 'am_michael', label: 'Michael (US male)', lang: 'en-US' },
  { id: 'am_adam', label: 'Adam (US male, deep)', lang: 'en-US' },
  { id: 'am_onyx', label: 'Onyx (US male, deep)', lang: 'en-US' },
  { id: 'am_fenrir', label: 'Fenrir (US male)', lang: 'en-US' },
  { id: 'am_eric', label: 'Eric (US male)', lang: 'en-US' },
  { id: 'am_liam', label: 'Liam (US male)', lang: 'en-US' },
  { id: 'am_echo', label: 'Echo (US male)', lang: 'en-US' },
  { id: 'am_puck', label: 'Puck (US male)', lang: 'en-US' },
  { id: 'bm_george', label: 'George (UK male)', lang: 'en-GB' },
  { id: 'bm_lewis', label: 'Lewis (UK male)', lang: 'en-GB' },
  { id: 'bm_daniel', label: 'Daniel (UK male)', lang: 'en-GB' },
  { id: 'bm_fable', label: 'Fable (UK male)', lang: 'en-GB' },
] as const;

const optionsFor = (
  engine: Engine,
  voices: readonly { id: string; label: string; lang: string }[],
  tag: string
): VoiceOption[] =>
  voices.map((voice) => ({
    name: `${ENGINE_PREFIX[engine]}${voice.id}`,
    displayName: `${voice.label} · ${tag}`,
    lang: voice.lang,
  }));

export const NEURAL_VOICE_OPTIONS: VoiceOption[] = [
  ...optionsFor('piper', PIPER_VOICES, 'Fast'),
  ...optionsFor('kokoro', KOKORO_VOICES, 'HD'),
];

const engineOf = (name?: string): Engine | undefined =>
  (Object.keys(ENGINE_PREFIX) as Engine[]).find((engine) =>
    name?.startsWith(ENGINE_PREFIX[engine])
  );

export const isNeuralVoice = (name?: string): name is string => engineOf(name) !== undefined;

const voiceIdOf = (name: string, engine: Engine): string =>
  name.slice(ENGINE_PREFIX[engine].length);

const workers: Partial<Record<Engine, Worker>> = {};
let audioContext: AudioContext | undefined;
let requestId = 0;
let playback: { id: number; nextStart: number; sources: AudioBufferSourceNode[] } | undefined;
let settle: { resolve: () => void; reject: (error: Error) => void } | undefined;

type WorkerEvent =
  | { type: 'ready' }
  | { type: 'status'; message: string }
  | { type: 'chunk'; id: number; samples: Float32Array; rate: number }
  | { type: 'done'; id: number }
  | { type: 'error'; id?: number; message: string };

const finish = (error?: Error): void => {
  const pending = settle;
  settle = undefined;
  if (error) pending?.reject(error);
  else pending?.resolve();
};

const schedule = (samples: Float32Array, rate: number): void => {
  if (!audioContext || !playback) return;
  const buffer = audioContext.createBuffer(1, samples.length, rate);
  buffer.copyToChannel(new Float32Array(samples), 0);
  const source = audioContext.createBufferSource();
  source.buffer = buffer;
  source.connect(audioContext.destination);
  const start = Math.max(playback.nextStart, audioContext.currentTime);
  source.start(start);
  playback.nextStart = start + buffer.duration;
  playback.sources.push(source);
};

const handleMessage = (event: MessageEvent<WorkerEvent>): void => {
  const message = event.data;
  if (message.type === 'status') {
    logger.info('Neural TTS:', message.message);
    return;
  }
  if (message.type === 'error') {
    logger.error('Neural TTS failed:', message.message);
    if (message.id === undefined || message.id === playback?.id) {
      finish(new Error(message.message));
    }
    return;
  }
  if (message.type === 'ready' || message.id !== playback?.id) return;
  if (message.type === 'chunk') {
    schedule(message.samples, message.rate);
    return;
  }
  const last = playback.sources.at(-1);
  if (last) last.onended = () => finish();
  else finish();
};

const createWorker = (engine: Engine): Worker =>
  engine === 'piper'
    ? new Worker(new URL('./piperTts.worker.ts', import.meta.url), { type: 'module' })
    : new Worker(new URL('./neuralTts.worker.ts', import.meta.url), { type: 'module' });

const getWorker = (engine: Engine): Worker => {
  if (!workers[engine]) {
    const created = createWorker(engine);
    created.onmessage = handleMessage;
    created.onerror = (event) => {
      logger.error('Neural TTS worker failed:', event.message, event.filename, event.lineno);
      delete workers[engine]; // next attempt starts a fresh worker
      finish(new Error(event.message || 'Neural TTS worker failed to load'));
    };
    workers[engine] = created;
  }
  return workers[engine];
};

// Starts the model download/init early so the first spoken line is not delayed.
export function preloadNeural(voiceName: string): void {
  const engine = engineOf(voiceName);
  if (engine) getWorker(engine).postMessage({ type: 'load', voice: voiceIdOf(voiceName, engine) });
}

export function stopNeural(): void {
  requestId += 1; // invalidates any generation still in flight
  Object.values(workers).forEach((worker) => worker.postMessage({ type: 'cancel', id: requestId }));
  playback?.sources.forEach((source) => {
    source.onended = null;
    try {
      source.stop();
    } catch {
      // never started
    }
  });
  playback = undefined;
  finish();
}

export async function speakNeural(text: string, voiceName: string): Promise<void> {
  const engine = engineOf(voiceName);
  if (!engine) throw new Error(`Not a neural voice: ${voiceName}`);
  stopNeural();
  const id = requestId;
  audioContext ??= new AudioContext();
  logger.info('Neural TTS: audio context', audioContext.state);
  await audioContext.resume(); // must happen inside the user's click gesture
  logger.info('Neural TTS: audio context resumed, sending to worker');
  playback = { id, nextStart: 0, sources: [] };
  return new Promise<void>((resolve, reject) => {
    settle = { resolve, reject };
    getWorker(engine).postMessage({
      type: 'speak',
      id,
      text,
      voice: voiceIdOf(voiceName, engine),
    });
  });
}
